// Chile tiene DST: UTC-3 en verano, UTC-4 en invierno
// Rango amplio cubre ambos casos
const date = $input.first().json.query?.date || new Date().toISOString().split('T')[0];
const [y, m, d] = date.split('-').map(Number);
const timeMin = new Date(Date.UTC(y, m-1, d, 3, 0, 0)).toISOString();    // 00:00 UTC-3
const timeMax = new Date(Date.UTC(y, m-1, d+1, 4, 0, 0)).toISOString();  // 00:00 UTC-4 siguiente día
return [{ json: { date, timeMin, timeMax } }];

// Slots deben coincidir con el frontend
const SLOTS = ['09:00', '10:30', '12:00', '15:00', '16:30', '18:00'];
const busy = [];

// Fecha consultada — evita bloquear otros días
const queriedDate = $('Preparar Rango').first().json.date;

for (const item of $input.all()) {
  const ev = item.json;
  if (!ev || !ev.start) continue;
  const startDT = ev.start.dateTime || ev.start.date;
  if (!startDT) continue;

  // Google Calendar devuelve la hora local en el dateTime
  // Ej: "2026-04-13T09:00:00-04:00" — leemos directo sin conversión UTC
  // Funciona con UTC-3 y UTC-4 (no rompe con cambio de horario)
  let localDate, hhmm;
  if (startDT.length >= 19 && (startDT[19] === '+' || startDT[19] === '-' || startDT[19] === 'Z')) {
    localDate = startDT.substring(0, 10);
    hhmm      = startDT.substring(11, 16);
  } else {
    localDate = startDT.substring(0, 10);
    hhmm      = startDT.length >= 16 ? startDT.substring(11, 16) : '00:00';
  }

  if (localDate !== queriedDate) continue;
  if (SLOTS.includes(hhmm) && !busy.includes(hhmm)) busy.push(hhmm);
}
return [{ json: { busy } }];

const b = $input.first().json.body || $input.first().json;
const fecha   = b.fecha;
const horaIni = b.hora;
const horaFin = b.hora_fin;
return [{
  json: {
    nombre:      b.nombre      || '',
    email:       b.email       || '',
    empresa:     b.empresa     || 'N/A',
    whatsapp:    b.whatsapp    || '',
    plan:        b.plan        || 'General',
    fecha_label: b.fecha_label || fecha,
    hora_label:  b.hora_label  || horaIni,
    timezone:    b.timezone    || 'America/Santiago',
    startISO: `${fecha}T${horaIni}:00`,
    endISO:   `${fecha}T${horaFin}:00`,
    summary:     `Reunión Orion.ia — ${b.nombre}`,
    description: `Nombre: ${b.nombre}\nEmail: ${b.email}\nWhatsApp: ${b.whatsapp}\nEmpresa: ${b.empresa||'N/A'}\nPlan: ${b.plan||'General'}\nFecha: ${b.fecha_label}\nHorario: ${b.hora_label}`
  }
}];
